package main
import("encoding/json";"fmt";"os";"runtime";"time")
var sink []byte
//go:noinline
func direct(size int) []byte { return make([]byte,size) }
//go:noinline
func appended(size int) []byte { return append([]byte(nil),make([]byte,size)...) }
type row struct { Compiler,Kind string;Size,Iterations int;Bytes uint64;Nanoseconds int64 }
func main(){
 rows:=make([]row,0,4)
 for _,size:=range []int{4096,65536}{
  for _,kind:=range []string{"direct","append-make"}{
   for range 8{sink=direct(size);sink=appended(size)}
   runtime.GC();var before,after runtime.MemStats;runtime.ReadMemStats(&before);start:=time.Now()
   for range 4096{if kind=="direct"{sink=direct(size)}else{sink=appended(size)};if len(sink)!=size||sink[0]!=0||sink[size-1]!=0{panic("incorrect zero slice")}}
   ns:=time.Since(start).Nanoseconds();runtime.ReadMemStats(&after)
   rows=append(rows,row{runtime.Compiler,kind,size,4096,after.TotalAlloc-before.TotalAlloc,ns})
  }
 }
 if err:=json.NewEncoder(os.Stdout).Encode(rows);err!=nil{fmt.Fprintln(os.Stderr,err);os.Exit(1)}
}
